+  font-weight: 600;
+  transition: background 0.15s;
+}
+#statBtn {
+  background: #333;
+  color: #fff;
+}
+#statBtn:hover { background: #555; }
+#clearBtn {
+  background: #e8e8e8;
+  color: #555;
+}
+#clearBtn:hover { background: #d8d8d8; }
+.result {
+  margin-top: 18px;
+  padding: 16px;
+  background: #fafafa;
+  border-radius: 8px;
+  display: none;
+}
+.result.show { display: block; }
+.result p {
+  font-size: 15px;
+  margin-bottom: 6px;
+}
+.result p:last-child { margin-bottom: 0; }
+.result .num {
+  font-weight: 700;
+  color: #333;
+}
